using UnityEngine;using UnityEditor;using UnityEngine.Rendering;using System.Collections.Generic;using System.IO;
namespace BankKit { public class BankGenerator:EditorWindow {
 const string Root="Assets/GeneratedBank"; int resolution=1024,segments=64; bool bricks=true; Material brick,stone,wood,roof,glass,metal,floor; Mesh cube; int serial; long tris;
 [MenuItem("Tools/Bank Kit/Generate Bank")] static void ShowWindow(){GetWindow<BankGenerator>("Bank Generator");}
 void OnGUI(){resolution=EditorGUILayout.IntPopup("Texture size",resolution,new[]{"512","1024","2048","4096"},new[]{512,1024,2048,4096});segments=EditorGUILayout.IntSlider("Curved geometry",segments,16,128);bricks=EditorGUILayout.Toggle("Individual brick geometry",bricks);if(GUILayout.Button("Generate model prefab"))Generate();}
 static Transform Group(Transform p,string n,Vector3 pos){var g=new GameObject(n).transform;g.SetParent(p,false);g.localPosition=pos;return g;}
 void SaveMesh(Mesh m){m.name="Mesh_"+(serial++);AssetDatabase.CreateAsset(m,Root+"/Meshes/"+m.name+".asset");}
 Mesh MeshOf(List<Vector3> v,List<int> t,List<Vector2> uv){var m=new Mesh();m.indexFormat=IndexFormat.UInt32;m.SetVertices(v);m.SetTriangles(t,0);m.SetUVs(0,uv);m.RecalculateNormals();m.RecalculateTangents();m.RecalculateBounds();SaveMesh(m);return m;}
 Mesh BoxMesh(){var v=new List<Vector3>();var t=new List<int>();var u=new List<Vector2>();Vector3[] ns={Vector3.right,Vector3.left,Vector3.up,Vector3.down,Vector3.forward,Vector3.back};foreach(var n in ns){var a=Mathf.Abs(n.y)>.5f?Vector3.right:Vector3.Cross(Vector3.up,n);var b=Vector3.Cross(n,a);int k=v.Count;v.Add((n-a-b)*.5f);v.Add((n+a-b)*.5f);v.Add((n+a+b)*.5f);v.Add((n-a+b)*.5f);u.Add(Vector2.zero);u.Add(Vector2.right);u.Add(Vector2.one);u.Add(Vector2.up);t.AddRange(new[]{k,k+1,k+2,k,k+2,k+3});}return MeshOf(v,t,u);}
 Transform Part(Transform p,string n,Mesh m,Material mat,Vector3 pos,Vector3 scale,bool coll=true){var g=Group(p,n,pos);g.localScale=scale;g.gameObject.AddComponent<MeshFilter>().sharedMesh=m;g.gameObject.AddComponent<MeshRenderer>().sharedMaterial=mat;if(coll){var b=g.gameObject.AddComponent<BoxCollider>();b.center=m.bounds.center;b.size=m.bounds.size;}tris+=m.triangles.Length/3;return g;}
 Transform Box(Transform p,string n,Vector3 pos,Vector3 s,Material mat,bool coll=true)=>Part(p,n,cube,mat,pos,s,coll);
 // Closed extruded polygon, front is negative Z. Input points counterclockwise.
 Mesh Extrude(Vector2[] poly,float depth){var v=new List<Vector3>();var t=new List<int>();var u=new List<Vector2>();int n=poly.Length;for(int side=0;side<2;side++){int k=v.Count;foreach(var q in poly){v.Add(new Vector3(q.x,q.y,(side-.5f)*depth));u.Add(q);}for(int i=1;i<n-1;i++){if(side==0)t.AddRange(new[]{k,k+i+1,k+i});else t.AddRange(new[]{k,k+i,k+i+1});}}for(int i=0;i<n;i++){var a=poly[i];var b=poly[(i+1)%n];int k=v.Count;v.Add(new Vector3(a.x,a.y,-depth/2));v.Add(new Vector3(b.x,b.y,-depth/2));v.Add(new Vector3(b.x,b.y,depth/2));v.Add(new Vector3(a.x,a.y,depth/2));u.AddRange(new[]{Vector2.zero,new Vector2(Vector2.Distance(a,b),0),new Vector2(Vector2.Distance(a,b),depth),new Vector2(0,depth)});t.AddRange(new[]{k,k+1,k+2,k,k+2,k+3});}return MeshOf(v,t,u);}
 void Shape(Transform p,string n,Vector2[] poly,float d,Material mat,Vector3 pos,bool coll=false){var g=Part(p,n,Extrude(poly,d),mat,pos,Vector3.one,false);if(coll){var c=g.gameObject.AddComponent<MeshCollider>();c.sharedMesh=g.GetComponent<MeshFilter>().sharedMesh;}}
 void Arch(Transform p,float x,float y,float z,float r,float width,Material mat){int count=Mathf.Max(12,segments/2);for(int i=0;i<count;i++){float a=i*Mathf.PI/count,b=(i+1)*Mathf.PI/count;Vector2 P(float q,float s)=>new Vector2(Mathf.Cos(q)*s,Mathf.Sin(q)*s);Shape(p,"Arch voussoir",new[]{P(a,r),P(a,r+width),P(b,r+width),P(b,r)},.28f,mat,new Vector3(x,y,z));}}
 Mesh ColumnMesh(){var v=new List<Vector3>();var t=new List<int>();var u=new List<Vector2>();int rings=24;for(int j=0;j<=rings;j++){float h=j/(float)rings;for(int i=0;i<=segments;i++){float a=i*2*Mathf.PI/segments;float r=(.32f-.055f*h)*(1+.10f*Mathf.Cos(a*16));v.Add(new Vector3(r*Mathf.Cos(a),h,r*Mathf.Sin(a)));u.Add(new Vector2(i/(float)segments,h));}}for(int j=0;j<rings;j++)for(int i=0;i<segments;i++){int k=j*(segments+1)+i;t.AddRange(new[]{k,k+segments+1,k+1,k+1,k+segments+1,k+segments+2});}return MeshOf(v,t,u);}
 void Column(Transform p,Mesh shaft,float x,float z,float h){Box(p,"Plinth",new Vector3(x,.2f,z),new Vector3(.95f,.4f,.95f),stone);Part(p,"Fluted shaft",shaft,stone,new Vector3(x,.4f,z),new Vector3(1,h-.9f,1));for(int i=0;i<4;i++)Box(p,"Capital",new Vector3(x,h-.5f+i*.12f,z),new Vector3(.65f+i*.09f,.12f,.65f+i*.09f),stone);}
 void Wall(Transform p,float x,float y,float z,float w,float h,float d){if(w<.015f||h<.015f)return;var g=Group(p,"Masonry panel",new Vector3(x,y,z));g.gameObject.AddComponent<BankBreakable>();int nx=bricks?Mathf.CeilToInt(w/.48f):Mathf.CeilToInt(w/1.2f),ny=bricks?Mathf.CeilToInt(h/.24f):Mathf.CeilToInt(h/.7f);float dx=w/nx,dy=h/ny;for(int j=0;j<ny;j++){int count=nx+(j%2);for(int i=0;i<count;i++){float a=Mathf.Max(0,(i-(j%2)*.5f)*dx),b=Mathf.Min(w,(i+1-(j%2)*.5f)*dx);if(b<=a)continue;Box(g,"Brick",new Vector3((a+b)/2-w/2,(j+.5f)*dy-h/2,0),new Vector3(b-a,dy,d),brick);}}}
 void WindowBay(Transform p,float x,float bottom,float z){float r=.72f,spring=bottom+2.45f;Wall(p,x,bottom+.35f,z,2.6f,.7f,.42f);foreach(int sign in new[]{-1,1})Wall(p,x+sign*1.01f,bottom+2.1f,z,.58f,2.8f,.42f); // wedge infill above curved aperture
 int n=segments/2;for(int i=0;i<n;i++){float a=-r+2*r*i/n,b=-r+2*r*(i+1)/n;float ya=Mathf.Sqrt(Mathf.Max(0,r*r-a*a)),yb=Mathf.Sqrt(Mathf.Max(0,r*r-b*b));Shape(p,"Curved brick infill",new[]{new Vector2(a,ya),new Vector2(b,yb),new Vector2(b,1.15f),new Vector2(a,1.15f)},.42f,brick,new Vector3(x,spring,z),true);}Wall(p,x-1.01f,spring+.575f,z,.58f,1.15f,.42f);Wall(p,x+1.01f,spring+.575f,z,.58f,1.15f,.42f);
 Box(p,"Glass",new Vector3(x,(bottom+.7f+spring)/2,z),new Vector3(r*2,spring-bottom-.7f,.045f),glass);var pts=new List<Vector2>{new Vector2(-r,0),new Vector2(r,0)};for(int i=1;i<n;i++){float a=i*Mathf.PI/n;pts.Add(new Vector2(r*Mathf.Cos(a),r*Mathf.Sin(a)));}Shape(p,"Fanlight glass",pts.ToArray(),.045f,glass,new Vector3(x,spring,z),true);Arch(p,x,spring,z-.24f,r,.16f,stone);foreach(int s in new[]{-1,1})Box(p,"Jamb",new Vector3(x+s*(r+.08f),(bottom+.7f+spring)/2,z-.24f),new Vector3(.16f,spring-bottom-.7f,.25f),stone);Box(p,"Mullion",new Vector3(x,bottom+1.9f,z-.27f),new Vector3(.065f,2.4f,.08f),metal);for(int j=0;j<3;j++)Box(p,"Transom",new Vector3(x,bottom+.85f+j*.75f,z-.27f),new Vector3(1.44f,.06f,.08f),metal);Box(p,"Sill",new Vector3(x,bottom+.68f,z-.25f),new Vector3(1.85f,.15f,.45f),stone);}
 Material MakeMat(string name,Color c,int mode,float metallic=0,float rough=.65f){int n=resolution;var h=new float[n*n];var al=new Color32[n*n];var ro=new Color32[n*n];var me=new Color32[n*n];var ao=new Color32[n*n];var he=new Color32[n*n];var no=new Color32[n*n];var packed=new Color32[n*n];for(int y=0;y<n;y++)for(int x=0;x<n;x++){float u=x/(float)n,v=y/(float)n;float noise=Mathf.PerlinNoise(u*35,v*35);float edge=1;if(mode==1||mode==2||mode==4){float rows=mode==1?8:mode==2?3:12;float cols=mode==1?4:mode==2?3:8;float yy=v*rows,xx=u*cols+((int)yy%2)*.5f;float a=Mathf.Repeat(xx,1),b=Mathf.Repeat(yy,1);edge=Mathf.Clamp01(Mathf.Min(Mathf.Min(a,1-a),Mathf.Min(b,1-b))*24);}float grain=mode==3?Mathf.PerlinNoise(u*80,v*3):noise;int i=y*n+x;h[i]=edge*.75f+grain*.15f;al[i]=Color.Lerp(new Color(.35f,.32f,.29f),c*(.72f+grain*.45f),edge);ro[i]=new Color(rough,rough,rough);me[i]=new Color(metallic,metallic,metallic);ao[i]=new Color(.55f+.45f*edge,.55f+.45f*edge,.55f+.45f*edge);he[i]=new Color(h[i],h[i],h[i]);packed[i]=new Color(metallic,0,0,1-rough);}for(int y=0;y<n;y++)for(int x=0;x<n;x++){float dx=h[y*n+(x+1)%n]-h[y*n+(x+n-1)%n],dy=h[((y+1)%n)*n+x]-h[((y+n-1)%n)*n+x];var q=new Vector3(-dx*4,-dy*4,1).normalized;no[y*n+x]=new Color(q.x*.5f+.5f,q.y*.5f+.5f,q.z*.5f+.5f);}Texture2D Save(string suffix,Color32[] pixels,bool linear,bool normal=false){var tex=new Texture2D(n,n,TextureFormat.RGBA32,false,linear);tex.SetPixels32(pixels);tex.Apply();string path=Root+"/Textures/"+name+"_"+suffix+".png";File.WriteAllBytes(path,tex.EncodeToPNG());DestroyImmediate(tex);AssetDatabase.ImportAsset(path);var imp=(TextureImporter)AssetImporter.GetAtPath(path);imp.sRGBTexture=!linear;imp.maxTextureSize=n;imp.wrapMode=TextureWrapMode.Repeat;if(normal)imp.textureType=TextureImporterType.NormalMap;imp.SaveAndReimport();return AssetDatabase.LoadAssetAtPath<Texture2D>(path);}var shader=Shader.Find("Universal Render Pipeline/Lit");if(!shader)shader=Shader.Find("Standard");var m=new Material(shader);var baseTex=Save("Albedo",al,false);m.SetTexture(m.HasProperty("_BaseMap")?"_BaseMap":"_MainTex",baseTex);m.SetTexture("_BumpMap",Save("Normal",no,true,true));m.EnableKeyword("_NORMALMAP");Save("Roughness",ro,true);Save("Metallic",me,true);m.SetTexture("_OcclusionMap",Save("AO",ao,true));m.EnableKeyword("_OCCLUSIONMAP");Save("Height",he,true);m.SetTexture("_MetallicGlossMap",Save("MetallicSmoothness",packed,true));m.EnableKeyword("_METALLICSPECGLOSSMAP");m.EnableKeyword("_METALLICGLOSSMAP");m.SetFloat("_Metallic",metallic);m.SetFloat("_Smoothness",1);if(name=="Glass"){if(m.HasProperty("_Surface")){m.SetFloat("_Surface",1);m.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");m.SetColor("_BaseColor",new Color(.65f,.8f,1,.3f));}else{m.SetFloat("_Mode",3);m.SetColor("_Color",new Color(.65f,.8f,1,.3f));m.EnableKeyword("_ALPHABLEND_ON");}m.SetInt("_SrcBlend",(int)BlendMode.SrcAlpha);m.SetInt("_DstBlend",(int)BlendMode.OneMinusSrcAlpha);m.SetInt("_ZWrite",0);m.renderQueue=3000;}AssetDatabase.CreateAsset(m,Root+"/Materials/"+name+".mat");return m;}
 void Door(Transform p){var g=Group(p,"Double entrance door",new Vector3(0,1,-6));var d=g.gameObject.AddComponent<BankDoor>();foreach(int s in new[]{-1,1}){var pivot=Group(g,s<0?"Left hinge":"Right hinge",new Vector3(s*1.19f,0,0));if(s<0)d.left=pivot;else d.right=pivot;float x=-s*.59f;Box(pivot,"Door leaf",new Vector3(x,1.35f,0),new Vector3(1.16f,2.7f,.13f),wood);for(int j=0;j<3;j++){Box(pivot,"Raised panel",new Vector3(x,.49f+j*.86f,-.085f),new Vector3(.87f,.67f,.06f),wood,false);foreach(int k in new[]{-1,1})Box(pivot,"Panel molding",new Vector3(x+k*.46f,.49f+j*.86f,-.12f),new Vector3(.045f,.75f,.05f),stone,false);}Box(pivot,"Brass handle",new Vector3(-s*1.03f,1.35f,-.18f),new Vector3(.045f,.28f,.09f),metal,false);}Arch(p,0,3.7f,-6.24f,1.2f,.25f,stone);var poly=new List<Vector2>{new Vector2(-1.2f,0),new Vector2(1.2f,0)};for(int i=1;i<segments;i++){float a=i*Mathf.PI/segments;poly.Add(new Vector2(1.2f*Mathf.Cos(a),1.2f*Mathf.Sin(a)));}Shape(p,"Entrance fanlight",poly.ToArray(),.06f,glass,new Vector3(0,3.7f,-6),true);for(int i=0;i<segments/2;i++){float a=-1.2f+2.4f*i/(segments/2),b=-1.2f+2.4f*(i+1)/(segments/2);float ya=Mathf.Sqrt(Mathf.Max(0,1.44f-a*a)),yb=Mathf.Sqrt(Mathf.Max(0,1.44f-b*b));Shape(p,"Door arch infill",new[]{new Vector2(a,ya),new Vector2(b,yb),new Vector2(b,1.3f),new Vector2(a,1.3f)},.42f,brick,new Vector3(0,3.7f,-6),true);}}
 void Roof(Transform p){float half=6.45f,rise=2.5f;float angle=Mathf.Atan2(rise,half)*Mathf.Rad2Deg;float length=Mathf.Sqrt(half*half+rise*rise);foreach(int s in new[]{-1,1}){var g=Group(p,"Roof slope",new Vector3(0,9+rise/2,s*half/2));g.localRotation=Quaternion.Euler(s*angle,0,0);Box(g,"Roof deck",Vector3.zero,new Vector3(20.5f,.18f,length),roof);for(int j=0;j<24;j++)for(int i=0;i<52;i++){float x=-10.1f+(i+.5f)*20.2f/52;float z=-length/2+(j+.5f)*length/24;Box(g,"Slate tile",new Vector3(x,.12f,z),new Vector3(.385f,.055f,length/24+.025f),roof,false);}}foreach(int s in new[]{-1,1}){var g=Group(p,"Gable end",new Vector3(s*10,9,0));g.localRotation=Quaternion.Euler(0,90,0);Shape(g,"Gable masonry",new[]{new Vector2(-6,0),new Vector2(6,0),new Vector2(0,rise)},.4f,brick,Vector3.zero,true);}Shape(p,"Front pediment",new[]{new Vector2(-4.1f,0),new Vector2(4.1f,0),new Vector2(0,2.1f)},.5f,stone,new Vector3(0,9,-6.65f),true);foreach(int s in new[]{-1,1}){var trim=Box(p,"Raking cornice",new Vector3(s*2.05f,10.05f,-7),new Vector3(4.7f,.19f,.65f),stone,false);trim.localRotation=Quaternion.Euler(0,0,-s*27);}}
 void Generate(){if(AssetDatabase.IsValidFolder(Root)){EditorUtility.DisplayDialog("Bank Kit","Rename or remove Assets/GeneratedBank before generating again. Existing assets are not overwritten.","OK");return;}GameObject model=null;try{Directory.CreateDirectory(Root+"/Meshes");Directory.CreateDirectory(Root+"/Materials");Directory.CreateDirectory(Root+"/Textures");AssetDatabase.Refresh();serial=0;tris=0;EditorUtility.DisplayProgressBar("Bank Kit","Creating PBR textures",.1f);brick=MakeMat("Brick",new Color(.57f,.23f,.12f),1);stone=MakeMat("Stone",new Color(.78f,.73f,.64f),2);wood=MakeMat("Wood",new Color(.36f,.18f,.08f),3);roof=MakeMat("Slate",new Color(.19f,.22f,.25f),4);glass=MakeMat("Glass",new Color(.5f,.7f,.85f),0,0,.08f);metal=MakeMat("Metal",new Color(.32f,.28f,.19f),0,.8f,.28f);floor=MakeMat("Floor",new Color(.8f,.78f,.73f),2);EditorUtility.DisplayProgressBar("Bank Kit","Building geometry",.5f);cube=BoxMesh();var shaft=ColumnMesh();model=new GameObject("Classic_Bank");model.AddComponent<BankDemoDamage>();var p=model.transform;var ext=Group(p,"Exterior",Vector3.zero);var inside=Group(p,"Interior",Vector3.zero);Box(inside,"Ground floor",new Vector3(0,.5f,0),new Vector3(20,1,12),floor);for(int j=0;j<5;j++)Box(ext,"Entrance step",new Vector3(0,(j+1)*.1f,-7.5f+j*.34f),new Vector3(4,(j+1)*.2f,.65f),stone);for(int level=0;level<2;level++){float y=1+level*4;foreach(float x in new[]{-7.8f,-5.2f,5.2f,7.8f})WindowBay(ext,x,y,-6);foreach(int s in new[]{-1,1}){Wall(ext,s*9.55f,y+2,-6,.9f,4,.42f);Wall(ext,s*3.05f,y+2,-6,1.7f,4,.42f);}if(level==0){Wall(ext,-1.57f,3,-6,.74f,4,.42f);Wall(ext,1.57f,3,-6,.74f,4,.42f);}else Wall(ext,0,y+2,-6,4.4f,4,.42f);for(int j=0;j<7;j++)Wall(ext,-8.5f+j*2.83f,y+2,6,2.83f,4,.42f);foreach(int s in new[]{-1,1}){var side=Group(ext,"Side facade",new Vector3(s*10,0,0));side.localRotation=Quaternion.Euler(0,s*90,0);for(int j=0;j<4;j++)WindowBay(side,-3.9f+j*2.6f,y,0);foreach(int k in new[]{-1,1})Wall(side,k*5.6f,y+2,0,.8f,4,.42f);}}Door(ext);foreach(float x in new[]{-3.65f,-2.45f,2.45f,3.65f})Column(ext,shaft,x,-6.7f,8.7f);foreach(float y in new[]{.85f,5f,8.85f,9f}){Box(ext,"Cornice front",new Vector3(0,y,-6.12f),new Vector3(20.5f,.19f,.65f),stone,false);Box(ext,"Cornice rear",new Vector3(0,y,6.12f),new Vector3(20.5f,.19f,.65f),stone,false);foreach(int s in new[]{-1,1})Box(ext,"Cornice side",new Vector3(s*10,y,0),new Vector3(.65f,.19f,12.6f),stone,false);} // upper floor has a genuine stair opening on left
 Box(inside,"Upper floor main",new Vector3(1.5f,4.85f,0),new Vector3(17,.3f,11.5f),floor);Box(inside,"Upper landing",new Vector3(-8.5f,4.85f,4.9f),new Vector3(3,.3f,1.7f),floor);Box(inside,"Upper front strip",new Vector3(-8.5f,4.85f,-4.9f),new Vector3(3,.3f,1.7f),floor);for(int i=0;i<20;i++){float h=(i+1)*.2f;Box(inside,"Stair tread",new Vector3(-8.5f,1+h/2,-3.8f+i*.4f),new Vector3(2.5f,h,.42f),wood);}for(int i=0;i<20;i++)Box(inside,"Baluster",new Vector3(-7.18f,1+(i+1)*.2f+.45f,-3.8f+i*.4f),new Vector3(.09f,.9f,.09f),wood);var rail=Box(inside,"Handrail",new Vector3(-7.18f,4,-.0f),new Vector3(.13f,.13f,8.8f),wood);rail.localRotation=Quaternion.Euler(-26.565f,0,0);for(int i=0;i<4;i++){Box(inside,"Teller counter",new Vector3(3+i*1.4f,1.55f,2.7f),new Vector3(1.35f,1.1f,.8f),wood);Box(inside,"Counter top",new Vector3(3+i*1.4f,2.13f,2.7f),new Vector3(1.42f,.12f,.95f),stone);Box(inside,"Office desk",new Vector3(1+i*2,5.45f,2),new Vector3(1.6f,.9f,.8f),wood);}Wall(inside,0,2.6f,4.7f,8,3.2f,.25f);Roof(ext);Box(ext,"Custom sign panel",new Vector3(0,8,-6.8f),new Vector3(4.1f,1.15f,.15f),metal,false);AssetDatabase.SaveAssets();string path=Root+"/Classic_Bank.prefab";PrefabUtility.SaveAsPrefabAsset(model,path);File.WriteAllText(Root+"/MeshStatistics.txt","Generated mesh instances triangles: "+tris+"\nCurved segments: "+segments+"\nTexture size: "+resolution);AssetDatabase.Refresh();Selection.activeObject=AssetDatabase.LoadAssetAtPath<GameObject>(path);Debug.Log("Bank generated: "+tris+" triangles (instances). "+path);}finally{if(model)DestroyImmediate(model);EditorUtility.ClearProgressBar();}} }
